// Generated by OpenAI Codex on 2026-11-03. Keyboard and pointer building selection.
import { useEffect, useId, useMemo, useState } from 'react';
import type { MapObject } from '../mapDocument';

export default function BuildingAutocomplete({
  buildings,
  value,
  disabled,
  onSelect,
}: {
  buildings: MapObject[];
  value: string | null;
  disabled: boolean;
  onSelect: (id: string | null) => void;
}) {
  const [query, setQuery] = useState(value || '');
  const [open, setOpen] = useState(false);
  const [active, setActive] = useState(0);
  const listId = useId();
  const selected = buildings.find((building) => building.id === value);
  const matches = useMemo(() => {
    const term = query.trim().toLowerCase();
    return buildings
      .map((building) => {
        const fields = [
          building.id,
          String(building.osm_id ?? ''),
          ...['name', 'alt_name', 'short_name', 'official_name'].flatMap((key) =>
            (building.tags[key] || '').split(';'),
          ),
        ].map((text) => text.trim().toLowerCase());
        const score = !term
          ? 3
          : fields.some((field) => field === term)
            ? 0
            : fields.some((field) => field.startsWith(term))
              ? 1
              : fields.some((field) => field.includes(term))
                ? 2
                : 4;
        return { building, score };
      })
      .filter((match) => match.score < 4)
      .sort(
        (a, b) =>
          a.score - b.score ||
          (a.building.tags.name || a.building.id).localeCompare(
            b.building.tags.name || b.building.id,
          ),
      )
      .slice(0, 20)
      .map((match) => match.building);
  }, [buildings, query]);
  const expanded = open && !disabled;
  useEffect(() => {
    if (expanded)
      document.getElementById(`${listId}-${active}`)?.scrollIntoView({ block: 'nearest' });
  }, [active, expanded, listId]);
  function choose(id: string) {
    setQuery(id);
    setOpen(false);
    if (id !== value) onSelect(id);
  }
  return (
    <div
      onBlur={(event) => {
        if (!event.currentTarget.contains(event.relatedTarget as Node | null)) setOpen(false);
      }}
    >
      <label htmlFor={`${listId}-input`}>Search building name or ID</label>
      <input
        id={`${listId}-input`}
        role="combobox"
        aria-label="Entrance building"
        aria-autocomplete="list"
        aria-expanded={expanded}
        aria-controls={listId}
        aria-activedescendant={expanded && matches[active] ? `${listId}-${active}` : undefined}
        disabled={disabled}
        value={query}
        placeholder="Name, alternative name, or building ID…"
        autoComplete="off"
        style={{ width: '100%' }}
        onFocus={() => {
          setOpen(true);
          setActive(0);
        }}
        onChange={(event) => {
          setQuery(event.target.value);
          setActive(0);
          setOpen(true);
        }}
        onKeyDown={(event) => {
          if (event.key === 'ArrowDown') {
            event.preventDefault();
            setOpen(true);
            setActive(open ? Math.max(0, Math.min(active + 1, matches.length - 1)) : 0);
          } else if (event.key === 'ArrowUp') {
            event.preventDefault();
            setOpen(true);
            setActive(Math.max(active - 1, 0));
          } else if (event.key === 'Enter') {
            event.preventDefault();
            if (matches[active]) choose(matches[active].id);
          } else if (event.key === 'Escape') {
            event.preventDefault();
            setOpen(false);
          }
        }}
      />
      {expanded && (
        <div
          id={listId}
          role="listbox"
          aria-label="Matching buildings"
          style={{
            maxHeight: 240,
            overflowY: 'auto',
            border: '1px solid #aeb9c4',
            borderRadius: 5,
          }}
        >
          {matches.map((building, index) => (
            <button
              type="button"
              role="option"
              aria-selected={index === active}
              id={`${listId}-${index}`}
              key={building.id}
              tabIndex={-1}
              onMouseDown={(event) => event.preventDefault()}
              onMouseEnter={() => setActive(index)}
              onClick={() => choose(building.id)}
              style={{
                display: 'block',
                width: '100%',
                margin: 0,
                textAlign: 'left',
                border: 0,
                borderRadius: 0,
                background: index === active ? '#dcecf9' : 'white',
                overflowWrap: 'anywhere',
              }}
            >
              <strong>{building.tags.name || 'Unnamed building'}</strong>
              <br />
              <small>
                {building.id}
                {building.osm_id != null ? ` · OSM ${building.osm_id}` : ''}
              </small>
            </button>
          ))}
          {!matches.length && (
            <p role="status" style={{ padding: 8 }}>
              No matching buildings. Try a different name or ID.
            </p>
          )}
        </div>
      )}
      <p>
        {selected ? `Linked to ${selected.tags.name || 'Unnamed building'}` : 'No building linked.'}{' '}
        Type to search, then press Enter or click a suggestion. Save to database to persist the
        link.
      </p>
      <button
        type="button"
        disabled={disabled || !value}
        onClick={() => {
          setQuery('');
          setOpen(false);
          onSelect(null);
        }}
      >
        Clear building link
      </button>
    </div>
  );
}
